exercises.solution:
struct Person {
    name: String,
}

impl Person {
    fn greet(&self) -> String {
        format!("Hello, {}", self.name)
    }
}

fn main() {
    let p = Person { name: "Alice".into() };
    println!("{}", p.greet());
}

