exercises.solution:
struct Person {
    name: String,
}

impl Person {
    fn set_name(&mut self, n: &str) {
        self.name = n.to_string();
    }
}

fn main() {
    let mut p = Person { name: "Bob".into() };
    p.set_name("Charlie");
    println!("{}", p.name);
}

