exercises.solution:
#[derive(Debug)]
struct Counter {
    value: i32,
}

impl Counter {
    fn increment(self) -> Self {
        Counter {
            value: self.value + 1,
        }
    }
}

fn main() {
    let c = Counter { value: 5 };
    println!("{:?}", c.increment());
}

