exercises.solution:
struct Builder {
    s: String,
}

impl Builder {
    fn new() -> Self {
        Self { s: String::new() }
    }
    fn add(mut self, t: &str) -> Self {
        self.s.push_str(t);
        self
    }
    fn build(self) -> String {
        self.s
    }
}

fn main() {
    let out = Builder::new().add("Hello").add("World").build();
    println!("{}", out);
}

